def contractive_shadowing_bound(delta: float, L: float) -> float:
    """Compute shadowing bound for contraction with ratio L."""
    assert 0 <= L < 1, f"Need L < 1, got {L}"
    return delta / (1.0 - L)

def make_certificate(f, orbit, L):
    delta = max(abs(orbit[i+1] - f(orbit[i])) for i in range(len(orbit)-1))
    bound = delta / (1.0 - L)
    shadow = [orbit[0]]
    for i in range(len(orbit)-1):
        shadow.append(f(shadow[-1]))
    return {'start': orbit[0], 'bound': bound, 'delta': delta, 'shadow': shadow}
